-- Migration: merchandiser_schedules reference table
-- Generated from 'DC' sheet of MERCHANDISER SCHEDULES AND PROPOSED DELIVERY SCHEDLUE 2026.xlsx
-- MGM sheet intentionally excluded (out of scope).

create extension if not exists pgcrypto;

create table if not exists merchandiser_schedules (
  id uuid primary key default gen_random_uuid(),
  plan text,
  portal_store_name text not null,
  nav_store_name text,
  banner text,
  store_code text,
  nav_code text,
  so_frequency text,
  merchandiser_name text,
  merchandiser_status text not null default 'UNKNOWN',
  merchandiser_contact text,
  schedule_raw text,
  schedule_days text[],
  is_stationary boolean not null default false,
  visit_time_window text,
  day_off text,
  company text,
  delivery_window_time text,
  sales_officer_name text,
  sales_officer_contact text,
  area_head_name text,
  area_head_contact text,
  region text,
  address text,
  delivery_schedule_1 text,
  delivery_schedule_2 text,
  area text,
  location text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists idx_merchandiser_schedules_portal_store_name on merchandiser_schedules (lower(portal_store_name));
create index if not exists idx_merchandiser_schedules_nav_store_name on merchandiser_schedules (lower(nav_store_name));
create index if not exists idx_merchandiser_schedules_banner on merchandiser_schedules (lower(banner));

alter table merchandiser_schedules enable row level security;

create policy "authenticated can read merchandiser_schedules" on merchandiser_schedules for select to authenticated using (true);
create policy "authenticated can update merchandiser_schedules" on merchandiser_schedules for update to authenticated using (true) with check (true);

grant select, update on merchandiser_schedules to authenticated;







-- Link route_plan_invoices to merchandiser_schedules (per-drop diser selection).
-- Additive/nullable columns; safe to run alongside existing data.
alter table route_plan_invoices
  add column if not exists merchandiser_schedule_id uuid references merchandiser_schedules(id),
  add column if not exists merchandiser_name_snapshot text,
  add column if not exists merchandiser_contact_snapshot text;

create index if not exists idx_route_plan_invoices_merchandiser_schedule_id
  on route_plan_invoices (merchandiser_schedule_id);
